 select t.empresa_id, t.id, t.abierto_por, 'retiro', 3600, 'emi', ('2026-10-07 20:30'::timestamp at time zone 'America/Argentina/Buenos_Aires')
 from caja_turnos t where t.notas = 'Traído de TPVsol · 2026-10-07' and not exists (select 1 from caja_movimientos x where x.turno_id = t.id and x.tipo = 'retiro' and x.monto = 3600);
insert into caja_movimientos (empresa_id, turno_id, user_id, tipo, monto, concepto, fecha)
 select t.empresa_id, t.id, t.abierto_por, 'retiro', 1000, 'emi', ('2026-10-17 20:15'::timestamp at time zone 'America/Argentina/Buenos_Aires')
 from caja_turnos t where t.notas = 'Traído de TPVsol · 2026-10-17' and not exists (select 1 from caja_movimientos x where x.turno_id = t.id and x.tipo = 'retiro' and x.monto = 1000);
-- las ventas del local de cada día (traídas de FactuSOL) quedan dentro de su turno
update ventas v set turno_id = t.id, caja_id = t.caja_id from caja_turnos t
 where t.notas like 'Traído de TPVsol · %' and t.empresa_id = v.empresa_id and v.turno_id is null and v.estado <> 'anulada'
   and v.origen in ('local', 'whatsapp') and (v.fecha at time zone 'America/Argentina/Buenos_Aires')::date = right(t.notas, 10)::date;
update venta_pagos p set turno_id = v.turno_id from ventas v, caja_turnos t
 where p.venta_id = v.id and v.turno_id = t.id and t.notas like 'Traído de TPVsol · %' and p.turno_id is distinct from v.turno_id;
commit;

select json_agg(json_build_object('dia', right(t.notas, 10), 'ini', t.efectivo_inicial, 'queda', t.efectivo_queda, 'ventas', (select count(*) from ventas v where v.turno_id = t.id), 'movs', (select count(*) from caja_movimientos m where m.turno_id = t.id)) order by t.abierto)::text from caja_turnos t where t.notas like 'Traído de TPVsol · %';
